import * as THREE from 'three';
export function effectOrder(layer,props){const order=(layer.effects||[]).map(f=>({...f})),present=new Set(order.map(f=>f.type));for(const type of ['blur','glow','shadow'])if(props[type]>0&&!present.has(type))order.push({type,enabled:true});return order.filter(f=>f.enabled!==false&&(['hue','saturation','brightness'].includes(f.type)||props[f.type]>0))}
const vertex='varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.,1.);}';
const fragment=`varying vec2 vUv;uniform sampler2D map;uniform vec2 resolution;uniform float mode,amount;uniform vec3 colorFx;
vec4 soft(vec2 uv,float radius){vec4 sum=vec4(0.);float total=0.;for(int x=-4;x<=4;x++)for(int y=-4;y<=4;y++){float w=exp(-float(x*x+y*y)/6.);vec4 s=texture2D(map,uv+vec2(float(x),float(y))*radius/resolution);sum+=vec4(s.rgb*s.a,s.a)*w;total+=w;}sum/=total;if(sum.a>.0001)sum.rgb/=sum.a;return sum;}
void main(){vec4 color=texture2D(map,vUv);if(mode<1.5){color=soft(vUv,amount);}else if(mode<2.5){vec4 g=soft(vUv,6.+amount*12.);color.rgb+=g.rgb*g.a*amount*.7;color.a=max(color.a,g.a*min(1.,amount));}else if(mode<3.5){vec4 s=soft(vUv-vec2(amount,-amount)/resolution,max(2.,amount*.3));float a=s.a*.45*(1.-color.a);color.rgb=color.rgb*color.a/max(.0001,color.a+a);color.a+=a;}else{float gray=dot(color.rgb,vec3(.2126,.7152,.0722));color.rgb=mix(vec3(gray),color.rgb,colorFx.y)*colorFx.z;vec3 axis=normalize(vec3(1.));color.rgb=color.rgb*cos(colorFx.x)+cross(axis,color.rgb)*sin(colorFx.x)+axis*dot(axis,color.rgb)*(1.-cos(colorFx.x));}gl_FragColor=color;}`;
export class LayerEffects{
 constructor(view){this.view=view;this.entries=new Map();this.scene=new THREE.Scene();this.camera=new THREE.Camera();this.pass=new THREE.ShaderMaterial({depthTest:false,depthWrite:false,uniforms:{map:{value:null},resolution:{value:new THREE.Vector2()},mode:{value:1},amount:{value:0},colorFx:{value:new THREE.Vector3(0,1,1)}},vertexShader:vertex,fragmentShader:fragment});this.screen=new THREE.Mesh(new THREE.PlaneGeometry(2,2),this.pass);this.scene.add(this.screen)}
 reset(){for(const e of this.entries.values())e.quad.visible=false}
 apply(objects){const view=this.view,renderer=view.renderer,active=objects.filter(o=>o.used&&o.root.visible&&o.mesh&&o.layer.type!=='adjustment'&&effectOrder(o.layer,o.props).length);for(const o of active){let entry=this.entries.get(o.path);if(!entry){const targets=Array.from({length:3},()=>new THREE.WebGLRenderTarget(...view.size,{type:THREE.HalfFloatType}));const material=new THREE.ShaderMaterial({transparent:true,depthTest:false,depthWrite:false,uniforms:{map:{value:null}},vertexShader:vertex,fragmentShader:'varying vec2 vUv;uniform sampler2D map;void main(){gl_FragColor=texture2D(map,vUv);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}'});const quad=new THREE.Mesh(new THREE.PlaneGeometry(2,2),material);quad.frustumCulled=false;view.scene.add(quad);entry={targets,quad,material};this.entries.set(o.path,entry)}entry.targets.forEach(rt=>rt.setSize(...view.size));entry.quad.renderOrder=1000+o.comp.layers.length-o.comp.layers.findIndex(l=>l.id===o.layer.id);const states=objects.map(q=>[q.root,q.root.visible]),effects=[...this.entries.values()].map(e=>[e.quad,e.quad.visible]);effects.forEach(([q])=>q.visible=false);for(const other of objects)other.root.visible=other===o||other.layer?.type==='light';const bg=view.scene.background,tone=renderer.toneMapping;view.scene.background=null;renderer.toneMapping=THREE.NoToneMapping;renderer.setRenderTarget(entry.targets[0]);renderer.clear();renderer.render(view.scene,view.camera);let input=entry.targets[0],at=0;for(const fx of effectOrder(o.layer,o.props)){const output=entry.targets[1+at%2],u=this.pass.uniforms;u.map.value=input.texture;u.resolution.value.set(...view.size);u.mode.value=({blur:1,glow:2,shadow:3,hue:4,saturation:4,brightness:4})[fx.type]||4;u.amount.value=o.props[fx.type];u.colorFx.value.set(o.props.hue*Math.PI/180,o.props.saturation,o.props.brightness);renderer.setRenderTarget(output);renderer.clear();renderer.render(this.scene,this.camera);input=output;at++}entry.material.uniforms.map.value=input.texture;renderer.setRenderTarget(null);renderer.toneMapping=tone;view.scene.background=bg;states.forEach(([q,v])=>q.visible=v);effects.forEach(([q,v])=>q.visible=v);o.root.visible=false;entry.quad.visible=true;}}
}
